        #node105_meta .spoiler2-header {
            padding-left: 25px;
            position: relative;
            cursor: pointer;
            margin-bottom: 6px;
            padding-bottom: 5px;
            border-bottom: 1px dashed rgba(0, 0, 0, 0.25);
        }

        #node105_meta .spoiler2-toggle {
            position: absolute;
            top: 11px;
            transform: translateY(-50%);
            left: 5px;
            font-size: 20px;
        }

